// Genereras av kallor-biologi/omrade3/exportsite.py (sajtkonv.py, latt_ov.py) – ändra inte för hand.
// Biologi område 3: varje moment i tre nivåer (lättläst, grundtext, fördjupning), skrivet för skärm i sajtens vanliga sidformat. Elevversion, utan facit. Lättläst har interaktiva övningar.
var innehall = window.innehall || {};
innehall["biologi-m-3-1-1"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "🌱", "titel": "Vad är biologisk mångfald?", "text": ["<p>Hur många olika sorters liv finns i en skog? Det är <strong>biologisk mångfald</strong>.</p>", "<p>Forskare har hittat drygt två miljoner arter. Ingen vet hur många som finns totalt.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade3/mangfald-tre-nivaer.png\" alt=\"\"></figure>", "<p>Mångfald är mer än antalet arter. Den finns på tre nivåer: <strong>gener</strong>, <strong>arter</strong> och <strong>ekosystem</strong>.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Biologisk mångfald är variationen av liv. Den finns som gener, arter och ekosystem.</div>"]}, {"ikon": "✏️", "titel": "Öva: Vad är biologisk mångfald?", "text": [], "ovningar": [{"typ": "ringa", "fraga": "Vad betyder biologisk mångfald?", "val": ["Variationen av liv", "Bara antalet djur", "Bara växter"], "ratt": 0}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["Ingen vet exakt hur många arter det finns.", "Mångfald betyder bara antal arter.", "Skogen har många olika arter."], "ratt": [true, false, true]}, {"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["arter", "ekosystem", "mångfald"], "meningar": ["Biologisk § är variationen av liv.", "Tall och gran är olika §.", "En skog och en myr är olika §."], "ratt": ["mångfald", "arter", "ekosystem"]}, {"typ": "skriv", "fraga": "Nämn tre arter som finns nära dig.", "borja": "Tre arter är", "forslag": "Till exempel tall, gran och blåbär."}]}, {"ikon": "📖", "titel": "Gener, arter och ekosystem", "text": ["<p>Mångfald finns på tre nivåer.</p>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Nivå</th><th>Exempel</th></tr><tr><td>Gener</td><td>Tallar med olika gener</td></tr><tr><td>Arter</td><td>Tall, gran, räv, flugsvamp</td></tr><tr><td>Ekosystem</td><td>Fjäll, skog, myr, älv</td></tr></table></div>", "<p><strong>Gener:</strong> Alla tallar är samma art, men deras gener är lite olika. Då kan någon tall klara torka eller kyla bättre.</p>", "<p><strong>Arter:</strong> En <strong>art</strong> är individer som kan få ungar tillsammans. Alla individer av en art i ett område kallas en <strong>population</strong>.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade3/mangfald-naringsvav.png\" alt=\"\"></figure>", "<p><strong>Ekosystem:</strong> Fjäll, skog och myr är olika ekosystem. Varje ekosystem har sina egna arter.</p>", "<p>Ett ekosystem med många arter klarar förändringar bättre. Om det blir färre sork kan räven äta något annat.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Mångfald finns som gener, arter och ekosystem. Många arter gör ekosystemet starkare.</div>"]}, {"ikon": "✏️", "titel": "Öva: Gener, arter och ekosystem", "text": [], "ovningar": [{"typ": "streck", "fraga": "Dra streck till rätt nivå.", "vanster": ["Gener", "Arter", "Ekosystem"], "hoger": ["myr och skog", "olika tallar", "tall och gran"], "ratt": ["olika tallar", "tall och gran", "myr och skog"]}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["Alla individer av en art är exakt lika.", "Fler arter gör ett ekosystem starkare.", "Räven kan äta olika djur."], "ratt": [false, true, true]}, {"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["art", "gener", "population"], "meningar": ["Alla tallar i en skog är en §.", "Tall är en §.", "Tallar skiljer sig lite i sina §."], "ratt": ["population", "art", "gener"]}, {"typ": "skriv", "fraga": "Varför är många arter bra för ett ekosystem?", "borja": "Det är bra eftersom", "forslag": "Om en art försvinner kan andra arter ta över, så ekosystemet klarar förändringar bättre."}]}]}, "vanlig": {"sektioner": [{"ikon": "🌱", "titel": "Hur mycket liv finns det?", "text": ["<p><strong>Biologisk mångfald</strong> betyder variationen av liv på jorden. Ordet används ofta om hur många arter som finns, men det är bara en del av sanningen. Forskare delar in mångfalden i <strong>tre nivåer</strong> som hänger ihop: gener, arter och ekosystem. Du lär dig dem i det första momentet.</p>", "<p>Forskare har hittills beskrivit drygt två miljoner arter, men hur många som finns totalt vet ingen. Uppskattningarna varierar från några miljoner till långt fler, och de flesta oupptäckta arterna är troligen insekter, svampar och mikroorganismer.</p>", "<p>I det här kapitlet svarar vi på fem frågor:</p>", "<ul><li>Vad är biologisk mångfald, och på vilka nivåer finns den?</li><li>Vad gör naturen för oss, och varför är mångfalden viktig för det?</li><li>Vad hotar mångfalden, och vad kan vi göra?</li><li>Hur ordnar forskare allt levande i grupper, och hur kan du själv bestämma en art?</li><li>Hur har arterna anpassat sig till sin miljö?</li></ul>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Vad är artrikast: en blåbärsskog eller en gräsmatta? Hur kan du ta reda på det?</div>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Delområde</th><th>Du lär dig</th></tr><tr><td><strong>3.1</strong> Mångfald, hot och ekosystemtjänster</td><td>Mångfaldens nivåer, vad naturen gör för oss, hoten mot mångfalden och vad vi kan göra. Labb: artinventering i en provruta.</td></tr><tr><td><strong>3.2</strong> Gruppera och organismvärlden</td><td>De fem rikena, bestämningsnycklar och hur arter anpassar sig. Labb: artbestämning med nyckel.</td></tr></table></div>"], "fragor": [{"f": "Vad menas med biologisk mångfald?", "svar": "Variationen av liv på jorden: gener, arter och ekosystem."}, {"f": "Varför räcker det inte att bara räkna antalet arter?", "svar": "Mångfald finns också inom arter (genetisk variation) och mellan livsmiljöer (ekosystem). Dessutom säger antalet inte hur arterna hänger ihop."}, {"f": "Vad vet forskarna om hur många arter det finns?", "svar": "Bara drygt två miljoner är beskrivna. Hur många som finns totalt vet ingen, men det är betydligt fler."}]}, {"ikon": "📖", "titel": "Gener, arter och ekosystem", "text": ["<p>Biologisk mångfald finns på tre nivåer: <strong>inom arter</strong>, <strong>mellan arter</strong> och <strong>mellan ekosystem</strong>. Alla tre är viktiga, och de påverkar varandra.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade3/mangfald-tre-nivaer.png\" alt=\"Bild 3.1 Biologisk mångfald finns på tre nivåer: inom arter, mellan arter och mellan ekosystem.\"><figcaption><strong>Bild 3.1</strong> Biologisk mångfald finns på tre nivåer: inom arter, mellan arter och mellan ekosystem.</figcaption></figure>"]}, {"ikon": "📖", "titel": "1. Genetisk mångfald: variation inom en art", "text": ["<p>Alla tallar tillhör samma art, men ingen tall är exakt lik en annan. Deras <strong>gener</strong> skiljer sig lite åt. En tall kanske tål torka bättre, en annan klarar kyla eller en viss svampsjukdom. När miljön förändras är det de individer som har ”rätt” gener som överlever och får ungar. Därför gör stor genetisk variation att en art kan anpassa sig.</p>"]}, {"ikon": "📖", "titel": "2. Artmångfald: variation mellan arter", "text": ["<p><strong>Artmångfald</strong> handlar om variationen mellan arter. Ett vanligt mått är <strong>artrikedom</strong>: antalet olika arter i ett område. En <strong>art</strong> är en grupp individer som kan para sig med varandra och få ungar som också kan få ungar. En blåbärsskog med hundratals arter av insekter, svampar och mossor har större artrikedom än en gräsmatta. Alla individer av en art i ett område kallas en <strong>population</strong>.</p>"]}, {"ikon": "🌱", "titel": "3. Ekosystemmångfald: variation mellan livsmiljöer", "text": ["<p>Fjäll, myr, gammal skog, älv och skärgård är olika ekosystem. Varje ekosystem har sina egna arter och sitt eget samspel. Om ett landskap bara har en typ av miljö, till exempel planterad skog i samma ålder, försvinner arter som behöver något annat.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Visste du?</span>Forskare har hittills beskrivit drygt två miljoner arter. Siffran är osäker, eftersom en del arter har fått flera namn. Hur många som finns totalt vet ingen: uppskattningarna går från några miljoner till betydligt fler.</div>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Varför räcker det inte att räkna antalet arter för att veta hur rik naturen är i ett område?</div>"]}, {"ikon": "📖", "titel": "Mångfald ger starka ekosystem", "text": ["<p>I ett ekosystem är alla arter beroende av varandra. Gröna växter är <strong>producenter</strong>: med hjälp av solljus bygger de upp socker med fotosyntes. Djur är <strong>konsumenter</strong> som får sin energi genom att äta växter eller andra djur. <strong>Nedbrytare</strong> som svampar och bakterier bryter ner döda växter och djur så att näringen kan användas igen. I naturen äter de flesta djur flera olika saker, så man ritar en <strong>näringsväv</strong> med många sammanflätade kedjor. Du får lära dig mer om detta i kapitel 4.</p>", "<p>Ett ekosystem med många arter är oftast mer motståndskraftigt. Vissa år blir det ont om sork. Då kan räven äta mer skogshare eller tjäder i stället. I ett artfattigt system finns det färre ”reservdelar”. Man kan jämföra med ett nät: du kan klippa av några trådar utan att det går sönder, men klipper du av för många rasar det.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Ett exempel från historien</span>På 1840-talet odlade man nästan bara en sorts potatis på Irland. Alla plantor var genetiskt mycket lika. När sjukdomen potatisbladmögel kom fanns inga plantor som tålde den. Skördarna slogs ut och omkring en miljon människor dog av svält.</div>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade3/mangfald-naringsvav.png\" alt=\"Bild 3.2 En förenklad näringsväv i en norrländsk barrskog. Pilarna visar åt vilket håll energin går: från den som blir äten till den som äter.\"><figcaption><strong>Bild 3.2</strong> En förenklad näringsväv i en norrländsk barrskog. Pilarna visar åt vilket håll energin går: från den som blir äten till den som äter.</figcaption></figure>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Titta på bild 3.2. Vad händer med räven om skogssorkarna blir färre? Vilken annan föda kan räven välja?</div>"], "fragor": [{"f": "Vilka är de tre nivåerna av biologisk mångfald? Ge ett exempel på varje.", "svar": "Genetisk mångfald (tallar med olika gener), artmångfald (gran, räv, flugsvamp) och ekosystemmångfald (fjäll, skog, myr, älv)."}, {"f": "Förklara med egna ord vad en art är.", "svar": "Individer som kan få fortplantningsdugliga ungar med varandra."}, {"f": "Varför kan stor genetisk variation hjälpa en art att överleva när klimatet blir varmare?", "svar": "Individerna har olika gener och tål olika saker. När klimatet ändras överlever de som har gener som passar, och de får ungar. Arten kan därför anpassa sig."}, {"f": "Förklara varför ett artrikt ekosystem klarar störningar bättre än ett artfattigt.", "svar": "Det finns fler arter som kan ta över en uppgift, till exempel fler arter som räven kan äta när sorken blir färre. Det är fler reservdelar."}]}], "begrepp": [{"term": "Art", "forklaring": "Individer som kan få fortplantningsdugliga ungar med varandra."}, {"term": "Artrikedom", "forklaring": "Antalet olika arter i ett område."}, {"term": "Biologisk mångfald", "forklaring": "Variationen av liv: genetisk mångfald, artmångfald och ekosystemmångfald."}, {"term": "Ekosystem", "forklaring": "Alla organismer i ett område och den miljö de lever i."}, {"term": "Gen", "forklaring": "En del av arvsmassan (DNA) som styr en egenskap."}, {"term": "Population", "forklaring": "Alla individer av en art inom ett område."}]}, "fordjupning": {"sektioner": [{"ikon": "🌱", "titel": "Vad är biologisk mångfald? Gener, arter och ekosystem", "text": ["<p>I grundtexten läste du att ett artrikt ekosystem ofta klarar störningar bättre. Här tittar vi närmare på <em>varför</em>. Förklaringen handlar om att arter är olika: de reagerar olika på samma störning.</p>", "<p><strong>Försäkringseffekten.</strong> Tänk dig en äng med tio växtarter. Under en torr sommar gynnas några arter, till exempel de med djupa rötter, medan andra tynar bort. Men eftersom några klarar torkan blir ängens totala växtmassa ändå ganska stor. På en äng med en enda art finns ingen sådan reserv: tål arten inte torkan, försvinner nästan allt. Skillnaderna mellan arter fungerar alltså som en <strong>försäkring</strong>. Förenklat: många arter betyder många olika svar på samma störning, och därför blir helheten stabilare.</p>", "<p><strong>Funktionell redundans.</strong> Om flera arter gör ungefär samma jobb i ekosystemet, till exempel flera arter av humlor som pollinerar blåbär, kan en art försvinna utan att tjänsten upphör. Men en art som är den enda som gör ett visst jobb går inte att ersätta. Därför räcker det inte att räkna arter: man måste också fråga <em>vad</em> de gör.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Varför ger en plantage med bara en trädart sämre försäkring än en blandskog, även om plantagen har många träd?</div>"]}, {"ikon": "📖", "titel": "Också inom arten", "text": ["<p>Samma tankegång gäller gener. När en population blir mycket liten förloras genetisk variation, och de individer som är kvar blir nära släkt. Det kallas en <strong>genetisk flaskhals</strong>. Då ökar risken för <strong>inavel</strong>, där ofördelaktiga gener oftare dyker upp hos ungarna, och populationen får svårare att anpassa sig om miljön ändras. För små, hotade populationer, som fjällräven, räcker det därför inte att öka antalet djur: man behöver också att de inte är för nära släkt.</p>", "<p>Det här är ett skäl till att man ibland flyttar djur mellan populationer för att hålla variationen uppe.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Visste du?</span>Potatisbladmögel slog ut skördarna på Irland på 1840-talet eftersom nästan alla potatisplantor var genetiskt mycket lika. Hade odlingarna haft större genetisk variation hade några plantor troligen klarat sjukdomen.</div>"]}], "begrepp": [{"term": "Försäkringseffekt", "forklaring": "Olika arter reagerar olika på störningar, så helheten blir stabilare."}, {"term": "Genetisk flaskhals", "forklaring": "När en population krymper kraftigt och mycket genetisk variation går förlorad."}, {"term": "Redundans", "forklaring": "Flera arter som kan ta över varandras uppgifter."}]}}, nivaStandard: "vanlig"};
innehall["biologi-m-3-1-2"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📖", "titel": "Ekosystemtjänster", "text": ["<p>Naturen gör saker som vi har nytta av. Det kallas <strong>ekosystemtjänster</strong>.</p>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Typ</th><th>Exempel</th></tr><tr><td>Försörjande</td><td>Bär, fisk, virke</td></tr><tr><td>Reglerande</td><td>Bin pollinerar. Myren renar vatten.</td></tr><tr><td>Stödjande</td><td>Bördig jord, fotosyntes</td></tr><tr><td>Kulturella</td><td>Friluftsliv, fiske</td></tr></table></div>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade3/ekotjanster.png\" alt=\"\"></figure>", "<p>Bin och humlor <strong>pollinerar</strong> blommor. Då kan blommorna bilda frön och bär. Utan pollinerare blir det mindre mat.</p>", "<p>Myrar tar upp vatten som en svamp. De renar vattnet och minskar översvämningar.</p>", "<p>Många olika arter gör tjänsterna säkrare. Om en art får det svårt kan andra ta över.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Ekosystemtjänster är sådant naturen gör som vi har nytta av. Det finns fyra typer.</div>"]}, {"ikon": "✏️", "titel": "Öva: Ekosystemtjänster", "text": [], "ovningar": [{"typ": "streck", "fraga": "Dra streck till rätt typ.", "vanster": ["Försörjande", "Reglerande", "Stödjande", "Kulturella"], "hoger": ["bin pollinerar", "bär och fisk", "bördig jord", "friluftsliv"], "ratt": ["bär och fisk", "bin pollinerar", "bördig jord", "friluftsliv"]}, {"typ": "ringa", "fraga": "Vad gör en myr?", "val": ["Renar vatten", "Gör ljus", "Tar bort alla arter"], "ratt": 0}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["Pollinering behövs för många bär.", "Naturens tjänster kostar alltid pengar.", "Fler arter gör tjänsterna säkrare."], "ratt": [true, false, true]}, {"typ": "skriv", "fraga": "Ge ett exempel på en ekosystemtjänst.", "borja": "Ett exempel är", "forslag": "Till exempel pollinering, vattenrening, bär eller friluftsliv."}]}]}, "vanlig": {"sektioner": [{"ikon": "📖", "titel": "Ekosystemtjänster", "text": ["<p>Allt vi äter, luften vi andas och vattnet vi dricker är beroende av andra arter. Det naturen gör för oss kallas <strong>ekosystemtjänster</strong>. De är gratis, och därför märker vi dem ofta inte förrän de slutar fungera. Man brukar dela in dem i fyra grupper.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade3/ekotjanster.png\" alt=\"Bild 3.3 De fyra typerna av ekosystemtjänster.\"><figcaption><strong>Bild 3.3</strong> De fyra typerna av ekosystemtjänster.</figcaption></figure>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Typ</th><th>Vad naturen gör</th><th>Exempel</th></tr><tr><td><strong>Försörjande</strong></td><td>Ger oss saker vi kan ta från naturen.</td><td>mat, fisk, bär, virke, rent vatten, ämnen till läkemedel</td></tr><tr><td><strong>Reglerande</strong></td><td>Styr och renar.</td><td>bin och humlor pollinerar, våtmarker renar vatten, skog tar upp koldioxid</td></tr><tr><td><strong>Stödjande</strong></td><td>Är grunden för allt annat.</td><td>nedbrytare gör jorden bördig, växter bildar syre med fotosyntes</td></tr><tr><td><strong>Kulturella</strong></td><td>Ger oss upplevelser och värden.</td><td>friluftsliv, jakt, fiske, vila, inspiration, kulturarv</td></tr></table></div>"]}, {"ikon": "📖", "titel": "Pollinering: en tjänst värd miljarder", "text": ["<p>När en humla flyger mellan blommor för att samla nektar för den med sig pollen. Då blir blommorna befruktade och kan bilda frön och bär. Utan pollinerare skulle det bli mycket mindre blåbär, lingon, äpplen och raps. Ungefär tre av fyra av de grödor vi odlar är beroende av pollinatörer i någon grad, och omkring en tredjedel av världens matproduktion (räknat i vikt) kommer från sådana grödor. Utan pollinatörer skulle den totala produktionen ändå minska med bara några procent, men frukt, bär och nötter skulle drabbas hårdast.</p>"]}, {"ikon": "📖", "titel": "Våtmarker och skog", "text": ["<p>En myr fungerar som en svamp: den suger upp vatten vid kraftiga regn och släpper ut det långsamt. Det minskar risken för översvämningar. Samtidigt fastnar näringsämnen och partiklar, så att vattnet som rinner vidare blir renare. Skogen tar upp koldioxid när träden växer och lagrar kol i stammar och i marken.</p>"]}, {"ikon": "📖", "titel": "Mångfald ger säkrare tjänster", "text": ["<p>Om det finns många olika arter som pollinerar spelar det mindre roll om en av dem får ett dåligt år. Därför är biologisk mångfald en sorts försäkring för ekosystemtjänsterna.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Visste du?</span>I vissa fruktodlingar i Kina har det funnits så få bin att människor har fått pollinera blommorna för hand med små penslar. Det tar lång tid och kostar mycket pengar.</div>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Vilken typ av ekosystemtjänst är en vandring i fjällen? Och bär som du plockar?</div>"], "fragor": [{"f": "Ge ett exempel på varje typ av ekosystemtjänst.", "svar": "Försörjande: bär, fisk, virke. Reglerande: pollinering, vattenrening. Stödjande: bördig jord, fotosyntes. Kulturella: friluftsliv, jakt, fiske."}, {"f": "Hur kan en myr minska risken för översvämningar?", "svar": "Den suger upp vatten vid kraftiga regn som en svamp och släpper ut det långsamt."}, {"f": "Förklara varför många olika arter av pollinerare är bättre än en enda.", "svar": "Om en art får ett dåligt år kan de andra fortfarande pollinera. Många arter gör tjänsten säkrare."}, {"f": "Vad är skillnaden mellan en försörjande och en reglerande ekosystemtjänst?", "svar": "Försörjande tjänster är saker vi tar från naturen (mat, virke). Reglerande tjänster är sådant naturen styr eller renar (pollinering, vattenrening, koldioxid)."}]}], "begrepp": [{"term": "Ekosystemtjänst", "forklaring": "Något som naturen gör och som människan har nytta av."}, {"term": "Pollinering", "forklaring": "När pollen förs från en blomma till en annan så att den kan bilda frön."}]}, "fordjupning": {"sektioner": [{"ikon": "📖", "titel": "Ekosystemtjänster", "text": ["<p>Alla arter är inte lika viktiga för hur ett ekosystem ser ut. Vissa arter påverkar mycket mer än deras antal skulle tyda på. De kallas <strong>nyckelarter</strong>.</p>", "<p><strong>Exempel: havsuttern.</strong> Vid Stillahavskusten i Nordamerika äter havsuttrar sjöborrar. Sjöborrar äter i sin tur tångskogar. När man jagade nästan ut havsuttrarna blev det fler sjöborrar, och sjöborrarna betade ner tångskogarna så att de försvann och med dem alla arter som levde där. När uttrarna fick skydd och kom tillbaka kunde tångskogarna återhämta sig. En förändring högst upp i näringskedjan fortplantade sig alltså nedåt. Det kallas en <strong>trofisk kaskad</strong>.</p>", "<p><strong>Exempel: bävern.</strong> Bävern dämmer vattendrag och skapar dammar och våtmarker. Det gynnar många andra arter, som grodor, fåglar och insekter, och påverkar också vattnets flöde och renhet. Bävern förändrar alltså själva miljön och kallas därför ibland <strong>ekosystemingenjör</strong>.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Rita en näringskedja med tång, sjöborre och havsutter. Vad händer med tången om uttrarna försvinner, och varför?</div>"]}, {"ikon": "✅", "titel": "Förenklingar och osäkerheter", "text": ["<p>Kaskader är ett bra sätt att förstå samband, men verkligheten är mer komplicerad än en rak kedja. De flesta djur äter flera olika saker, och flera faktorer verkar samtidigt: klimat, sjukdomar och människan. Därför är det svårt att veta exakt hur mycket just en art förklarar. När forskare ska avgöra om en art är en nyckelart jämför de ofta områden med och utan arten, och försöker hålla övrigt lika. Även då är resultaten ibland omdiskuterade.</p>"]}], "begrepp": [{"term": "Ekosystemingenjör", "forklaring": "En art som skapar eller förändrar miljön åt andra."}, {"term": "Nyckelart", "forklaring": "En art som påverkar ekosystemet mycket mer än vad dess antal motsvarar."}, {"term": "Trofisk kaskad", "forklaring": "När en förändring på en nivå i näringsväven fortplantar sig till andra nivåer."}]}}, nivaStandard: "vanlig"};
innehall["biologi-m-3-1-3"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📖", "titel": "Hoten mot mångfalden", "text": ["<p>Arter dör ut i dag mycket snabbare än förr. FN:s experter säger att cirka en miljon arter är hotade. Orsaken är oftast människan.</p>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Hot</th><th>Exempel</th></tr><tr><td>Ändrad markanvändning</td><td>Skog avverkas</td></tr><tr><td>Överuttag</td><td>Överfiske</td></tr><tr><td>Klimatförändringar</td><td>Det blir varmare</td></tr><tr><td>Föroreningar</td><td>Plast i havet</td></tr><tr><td>Invasiva arter</td><td>Blomsterlupin</td></tr></table></div>", "<p>Forskare gör en <strong>rödlista</strong>. Den visar vilka arter i Sverige som kan försvinna. I Rödlistan 2025 var 5 217 arter rödlistade.</p>", "<p><strong>Fjällräven</strong> är hotad. Den jagades förr. Nu har den svårt att få mat, och rödräven tränger undan den.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade3/mangfald-fjallrav-rodrav.png\" alt=\"\"></figure>", "<p><strong>Gammal skog</strong> är hem för många arter. Garnlav är en <strong>signalart</strong>. Den visar att skogen är gammal och värdefull.</p>", "<p>Vi kan skydda arter med nationalparker och naturreservat. Vi kan också välja hållbart fiskad mat och låta en del av gräsmattan bli äng.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Hoten är ändrad markanvändning, överuttag, klimatförändringar, föroreningar och invasiva arter. Rödlistan visar vilka arter som är hotade.</div>"]}, {"ikon": "✏️", "titel": "Öva: Hoten mot mångfalden", "text": [], "ovningar": [{"typ": "ringa", "fraga": "Vad visar rödlistan?", "val": ["Vilka arter som kan dö ut", "Vilka arter som är störst", "Vilka arter som är farliga"], "ratt": 0}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["Överfiske är ett hot.", "Garnlav visar att skogen är gammal.", "Alla arter är lika vanliga."], "ratt": [true, true, false]}, {"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["invasiv", "klimatet", "skog"], "meningar": ["Om § blir varmare måste arter flytta.", "När gammal § avverkas försvinner livsmiljöer.", "Blomsterlupin är en § art."], "ratt": ["klimatet", "skog", "invasiv"]}, {"typ": "skriv", "fraga": "Nämn två hot mot mångfalden.", "borja": "Två hot är", "forslag": "Till exempel överfiske och avverkad skog."}]}]}, "vanlig": {"sektioner": [{"ikon": "📖", "titel": "Hoten mot mångfalden", "text": ["<p>Arter har alltid dött ut och nya har utvecklats. Men i dag försvinner arter mycket snabbare än vad som är naturligt. FN:s expertpanel för biologisk mångfald, IPBES, bedömde 2019 att omkring en miljon djur- och växtarter är hotade av utrotning, många inom några årtionden. Nästan alla hot har samma grundorsak: människans aktiviteter. De fem största hoten, i den ordning IPBES rangordnar dem, är:</p>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Hot</th><th>Vad det innebär</th><th>Exempel</th></tr><tr><td><strong>1. Ändrad mark- och havsanvändning</strong></td><td>Livsmiljöer försvinner eller delas upp.</td><td>skog avverkas, myrar dikas, ängar växer igen</td></tr><tr><td><strong>2. Överuttag</strong></td><td>Vi fiskar, jagar eller skördar mer än vad som hinner växa till.</td><td>överfiske, tjuvjakt</td></tr><tr><td><strong>3. Klimatförändringar</strong></td><td>Arter måste flytta norrut eller uppåt.</td><td>fjällens arter har ingenstans att ta vägen</td></tr><tr><td><strong>4. Föroreningar</strong></td><td>Miljögifter, plast och övergödning skadar liv i mark och vatten.</td><td>övergödda sjöar, plast i havet</td></tr><tr><td><strong>5. Invasiva arter</strong></td><td>Främmande arter som människan fört in tränger undan de inhemska.</td><td>blomsterlupin</td></tr></table></div>"]}, {"ikon": "📖", "titel": "Rödlistan: Sveriges hälsokontroll", "text": ["<p>Ungefär vart femte år bedömer forskare vid SLU Artdatabanken hur stor risken är att olika arter försvinner från Sverige. Resultatet kallas <strong>rödlistan</strong>. I den senaste rödlistan, Rödlistan 2025, bedömdes 23 103 arter. Av dem var 5 217 rödlistade, och 2 373 räknades som hotade. Arter i kategorierna VU (sårbar), EN (starkt hotad) och CR (akut hotad) räknas som hotade. DD betyder att forskarna vet för lite om arten för att kunna bedöma den.</p>", "<p>Enligt Naturvårdsverket är igenväxning och avverkning de viktigaste negativa påverkansfaktorerna för rödlistade arter i Sverige, och jordbruks- och skogslandskapen hyser tillsammans över 75 procent av de rödlistade arterna. Bland de rödlistade finns också djur som många känner till, till exempel ålen. Men det finns goda nyheter: uttern och havsörnen har blivit så många igen att de inte längre är rödlistade.</p>", "<div class=\"ruta ruta-fakta\"><span class=\"ruta-rubrik\">Granska kritiskt</span>Mellan år 2000 och 2025 ökade också antalet arter som forskarna bedömde, från cirka 19 000 till drygt 23 000. Betyder det att alla nya rödlistade arter i diagrammet har fått det sämre? Vilken annan förklaring kan finnas?</div>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade3/mangfald-rodlista-diagram.png\" alt=\"Bild 3.4 Antal rödlistade arter i Sverige. Källa: SLU Artdatabanken.\"><figcaption><strong>Bild 3.4</strong> Antal rödlistade arter i Sverige. Källa: SLU Artdatabanken.</figcaption></figure>"]}, {"ikon": "📖", "titel": "Mångfald i Norrbotten", "text": ["<p><strong>Fjällräven</strong> jagades hårt för sin vackra vinterpäls. Den blev fridlyst 1928, men stammen återhämtade sig inte. Runt år 2000 uppskattade forskare att det bara fanns cirka 35–50 vuxna fjällrävar i hela Skandinavien. Fjällräven lever mest av lämlar, och lämmelåren har blivit ovanligare. Dessutom tar sig rödräven allt högre upp på fjället. Den är större och konkurrerar om både mat och lyor. Med stödutfodring och jakt på rödräv har fjällräven ökat igen, men den är fortfarande hotad.</p>", "<p><strong>Gammal skog</strong> som aldrig har kalavverkats har gamla träd, död ved och hängande lavar. Många arter kan bara leva där. Ett exempel är <strong>garnlaven</strong>, som hänger i långa grågröna trådar från granar. Den kallas en <strong>signalart</strong>: hittar man den är skogen troligen gammal och artrik. Hänglavar är också viktig vinterföda för renarna.</p>", "<p>Torne älv, Kalix älv, Pite älv och Vindelälven är Sveriges fyra nationalälvar. De skyddas av lag mot nya vattenkraftsutbyggnader.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade3/mangfald-fjallrav-rodrav.png\" alt=\"Bild 3.5 Fjällräven (till vänster) är mindre och har kort nos och små öron. Rödräven har längre ben och stora öron.\"><figcaption><strong>Bild 3.5</strong> Fjällräven (till vänster) är mindre och har kort nos och små öron. Rödräven har längre ben och stora öron.</figcaption></figure>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade3/mangfald-garnlav.png\" alt=\"Bild 3.6 Garnlav, en signalart.\"><figcaption><strong>Bild 3.6</strong> Garnlav, en signalart.</figcaption></figure>"]}, {"ikon": "❓", "titel": "Samhällsfrågan: vad ska skogen användas till?", "text": ["<p>Skogen i Norrbotten ger jobb, virke och biobränsle. Den är också hem för tusentals arter och betesmark för renar. Olika grupper ser olika saker i samma skog.</p>", "<div class=\"kort-rad\"><div class=\"kort\"><strong>Skogsbolaget</strong>”Skogsbruket ger jobb i hela länet och virke som kan ersätta plast och betong. Vi lämnar kvar gamla träd och skyddar värdefulla områden.”</div><div class=\"kort\"><strong>Naturskyddsförening</strong>”Det finns för lite gammal skog kvar. Kalhyggen förstör livsmiljöer som tar hundratals år att bygga upp igen.”</div><div class=\"kort\"><strong>Renskötaren</strong>”När gammal skog avverkas försvinner hänglaven. Då har renarna mindre att äta på vintern.”</div><div class=\"kort\"><strong>Kommunen</strong>”Vi behöver både arbetstillfällen och natur som lockar turister och gör det skönt att bo här.”</div></div>", "<p class=\"not\">Citaten är konstruerade för att visa olika perspektiv och är inte ordagranna uttalanden.</p>"]}, {"ikon": "📖", "titel": "Vad kan vi göra?", "text": ["<p>Det viktigaste för att skydda den biologiska mångfalden är att bevara och återskapa livsmiljöer. Det sker på flera nivåer samtidigt. År 2022 kom världens länder överens om att skydda och bevara minst 30 procent av jordens land, sötvatten och hav till år 2030. I Sverige skyddar nationalparker och naturreservat natur, och lagar styr skogsbruk, jakt och fiske. I Norrbotten finns världsarvet Laponia med bland annat Sarek och Padjelanta.</p>", "<p>Ibland behöver naturen hjälp att återhämta sig. Man kan till exempel dämma igen diken så att en myr blir blöt igen, låta kor beta igenvuxna ängar eller bränna skog under kontroll, eftersom många arter är anpassade till skogsbränder. Du själv kan låta en bit gräsmatta bli äng, välja hållbart fiskad mat, rapportera arter du ser i Artportalen och aldrig slänga trädgårdsväxter i naturen.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Vilka tre saker kan du göra själv för att gynna mångfalden där du bor?</div>"], "fragor": [{"f": "Nämn tre hot mot den biologiska mångfalden och ge ett exempel på varje.", "svar": "T.ex. ändrad markanvändning (avverkad skog), överuttag (överfiske), klimatförändringar, föroreningar (plast, miljögifter) och invasiva arter (blomsterlupin)."}, {"f": "Vad är en rödlista?", "svar": "En förteckning över arter och hur stor risken är att de försvinner, som forskare vid SLU Artdatabanken uppdaterar."}, {"f": "Ge två orsaker till att fjällräven har haft svårt att öka.", "svar": "T.ex. jakt förr, brist på lämlar och att rödräven konkurrerar om mat och lyor."}, {"f": "Vad är en signalart? Ge ett exempel.", "svar": "En art som visar att en miljö har höga naturvärden, t.ex. garnlav som visar gammal skog."}, {"f": "Ge ett argument för och ett emot att avverka en gammal skog.", "svar": "För: jobb och virke. Emot: livsmiljöer för många arter försvinner och tar hundratals år att återskapa."}]}], "begrepp": [{"term": "Invasiv art", "forklaring": "En art som människan fört in och som sprider sig och skadar inhemska arter."}, {"term": "Livsmiljö", "forklaring": "Den plats där en art kan leva och föröka sig."}, {"term": "Rödlista", "forklaring": "Förteckning över arter och deras risk att dö ut."}, {"term": "Signalart", "forklaring": "Art som visar att en miljö har höga naturvärden."}, {"term": "Överuttag", "forklaring": "När människan tar mer ur naturen än vad som hinner växa till."}]}, "fordjupning": {"sektioner": [{"ikon": "📖", "titel": "Hoten mot mångfalden", "text": ["<p>I grundtexten lärde du dig fem hot var för sig. I verkligheten verkar de ofta samtidigt och förstärker varandra.</p>", "<p><strong>Exempel: fjällräven.</strong> Fjällräven har påverkats av flera saker samtidigt: den jagades hårt, födan (lämlar) varierar kraftigt, och rödräven konkurrerar om mat och lyor och tar sig högre upp i fjällen. Ett varmare klimat kan göra att skogsgränsen flyttar uppåt och ger rödräven mer plats. Varje faktor för sig kanske vore hanterbar, men tillsammans blir pressen stor, och när populationen är liten blir den också känsligare för slumpen.</p>", "<p><strong>Exempel: överfiske.</strong> När många fiskar samma bestånd tar de mer än vad som hinner växa till. Då kan beståndet kollapsa. Ett känt exempel är torsken utanför Newfoundland, där fisket stoppades 1992 efter att beståndet hade rasat. Även efter stoppet tog återhämtningen mycket lång tid. Det visar att det kan vara lättare att förstöra ett ekosystem än att bygga upp det igen.</p>", "<div class=\"ruta ruta-fakta\"><span class=\"ruta-rubrik\">Granska kritiskt</span>Någon säger: ”Fjällräven har minskat på grund av rödräven.” Varför är det ett förenklat påstående? Vilka andra förklaringar finns, och hur skulle man kunna undersöka vad som väger tyngst?</div>"]}, {"ikon": "✅", "titel": "Att värdera åtgärder", "text": ["<p>Att skydda natur kostar pengar eller begränsar vad människor får göra. Därför måste man värdera både nytta och kostnad, och fråga vem som får nyttan och vem som betalar. Några frågor som hjälper dig att resonera: Vilka grupper berörs? Hur säkra är kunskaperna? Går skadan att reparera? Finns det mindre ingripande alternativ? Ett välgrundat ställningstagande väger flera argument mot varandra och säger också vad man är osäker på.</p>"]}], "begrepp": [{"term": "Förebyggande åtgärd", "forklaring": "Något man gör innan skadan har hänt."}, {"term": "Intressekonflikt", "forklaring": "När olika grupper vill använda samma resurs på olika sätt."}, {"term": "Kollaps", "forklaring": "När ett bestånd eller ekosystem snabbt minskar kraftigt."}]}}, nivaStandard: "vanlig"};
innehall["biologi-m-3-1-l"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "🧪", "titel": "Labb 3.1 Artinventering i en provruta", "text": ["<p><strong>Fråga:</strong> Finns det fler växtarter på en äng än på en klippt gräsmatta?</p>", "<p>Du behöver: fyra pinnar, snöre, tumstock, mobil och papper.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade3/mangfald-provruta.png\" alt=\"\"></figure>", "<ol><li>Märk ut en ruta på 1 × 1 meter på ängen.</li><li>Räkna hur många olika växtarter som finns. Ta bilder och ge dem nummer.</li><li>Gör likadant på gräsmattan.</li><li>Gör tre rutor på varje plats.</li><li>Skriv resultatet i tabellen.</li></ol>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Plats</th><th>Ruta 1</th><th>Ruta 2</th><th>Ruta 3</th></tr><tr><td>Äng</td><td></td><td></td><td></td></tr><tr><td>Gräsmatta</td><td></td><td></td><td></td></tr></table></div>", "<p><strong>Säkerhet:</strong> Smaka inte på växter. Följ allemansrätten. Tvätta händerna efteråt.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Man räknar i flera rutor för att få ett säkrare resultat.</div>"]}, {"ikon": "✏️", "titel": "Öva: Labb 3.1 Artinventering i en provruta", "text": [], "ovningar": [{"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["arter", "fler", "rutor"], "meningar": ["Vi räknade § som fanns i rutan.", "Vi gjorde tre § på varje plats.", "Ängen hade § arter än gräsmattan."], "ratt": ["arter", "rutor", "fler"]}, {"typ": "skriv", "fraga": "Stämde din gissning? Skriv vad som hände.", "borja": "Min gissning", "forslag": "Egna resultat: skriv om ängen hade fler arter än gräsmattan."}, {"typ": "skriv", "fraga": "Varför gör vi tre rutor och inte bara en?", "borja": "Vi gör tre rutor eftersom", "forslag": "Man gör flera rutor för att få ett säkrare resultat."}]}]}, "vanlig": {"sektioner": [{"ikon": "🧪", "titel": "Labb 3.1 Artinventering i en provruta", "text": ["<p>Du ska undersöka artrikedom med en enkel fältstudie: hur många olika växtsorter finns det i en kvadratmeter på två olika platser?</p>", "<p><strong>Frågeställning:</strong> Finns det fler växtarter på en ängsmark än på en klippt gräsmatta?</p>", "<p><strong>Hypotes:</strong> Skriv vad du tror och varför innan du börjar.</p>", "<p><strong>Material:</strong> fyra pinnar, snöre (ca 5 m), tumstock, mobilkamera eller artbok/app, papper och penna.</p>"]}, {"ikon": "📖", "titel": "Gör så här", "text": ["<ol><li>Märk ut en ruta på 1 × 1 meter med pinnar och snöre på ängen.</li><li>Räkna hur många olika växtarter som finns i rutan. Du behöver inte veta vad de heter: ta en bild och ge dem nummer.</li><li>Gör likadant på gräsmattan.</li><li>Upprepa med minst tre rutor på varje plats. Varför är det viktigt?</li><li>Skriv in resultatet i en tabell och räkna ut medelvärdet för varje plats.</li></ol>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade3/mangfald-provruta.png\" alt=\"Bild 3.7 En provruta på 1 m².\"><figcaption><strong>Bild 3.7</strong> En provruta på 1 m².</figcaption></figure>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Plats</th><th>Ruta 1</th><th>Ruta 2</th><th>Ruta 3</th><th>Medelvärde</th></tr><tr><td>Äng</td><td></td><td></td><td></td><td></td></tr><tr><td>Gräsmatta</td><td></td><td></td><td></td><td></td></tr></table></div>"]}, {"ikon": "✅", "titel": "Utvärdera", "text": ["<ol><li>Stämde din hypotes?</li><li>Vad kan ha påverkat resultatet, till exempel tid på året, var du lade rutan eller om du kunde skilja arterna åt?</li><li>Hur skulle du göra undersökningen mer tillförlitlig, alltså så att man kan lita på resultatet?</li></ol>", "<p class=\"not\">Säkerhet: Smaka aldrig på växter eller svampar. Följ allemansrätten och lämna platsen som du fann den. Tvätta händerna efteråt.</p>"]}], "begrepp": [{"term": "Inventering", "forklaring": "Att räkna och notera vilka arter som finns."}, {"term": "Medelvärde", "forklaring": "Summan delat med antalet."}, {"term": "Provruta", "forklaring": "Ett avgränsat område där man räknar."}]}}, nivaStandard: "vanlig"};
innehall["biologi-m-3-2-1"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📖", "titel": "Rikena", "text": ["<p>Forskare delar in allt levande i grupper. De största grupperna kallas <strong>riken</strong>.</p>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Rike</th><th>Exempel</th><th>Näring</th></tr><tr><td>Djur</td><td>Räv, älg</td><td>Äter andra</td></tr><tr><td>Växter</td><td>Tall, blåbär</td><td>Fotosyntes</td></tr><tr><td>Svampar</td><td>Flugsvamp</td><td>Tar från död materia</td></tr><tr><td>Bakterier</td><td>Tarmbakterier</td><td>Olika sätt</td></tr><tr><td>Encelliga med kärna</td><td>Amöba</td><td>Olika sätt</td></tr></table></div>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade3/rikena.png\" alt=\"\"></figure>", "<p>Svampar är inte växter. De gör ingen fotosyntes. De bryter ner döda växter och djur.</p>", "<p>En <strong>lav</strong> är en svamp och en alg som lever ihop. De hjälper varandra.</p>", "<p>Varje art har ett <strong>vetenskapligt namn</strong> med två ord på latin. Tall heter <em>Pinus sylvestris</em>.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Det finns fem riken: djur, växter, svampar, bakterier och encelliga organismer med cellkärna.</div>"]}, {"ikon": "✏️", "titel": "Öva: Rikena", "text": [], "ovningar": [{"typ": "streck", "fraga": "Dra streck till rätt rike.", "vanster": ["Räv", "Tall", "Flugsvamp", "Tarmbakterie"], "hoger": ["Bakterier", "Djur", "Svampar", "Växter"], "ratt": ["Djur", "Växter", "Svampar", "Bakterier"]}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["Svampar är växter.", "En lav är en svamp och en alg.", "Varje art har ett latinskt namn."], "ratt": [false, true, true]}, {"typ": "ringa", "fraga": "Vilket rike gör fotosyntes?", "val": ["Växter", "Djur", "Svampar"], "ratt": 0}, {"typ": "skriv", "fraga": "Nämn tre av de fem rikena.", "borja": "Tre riken är", "forslag": "Till exempel djur, växter och svampar."}]}]}, "vanlig": {"sektioner": [{"ikon": "📖", "titel": "Rikena", "text": ["<p>Med över två miljoner kända arter behövs ordning. Forskare delar in organismerna i grupper efter hur de är byggda och hur de är släkt med varandra. De största grupperna kallas <strong>riken</strong>. Här använder vi fem: <strong>djur</strong>, <strong>växter</strong>, <strong>svampar</strong>, <strong>bakterier</strong> och <strong>encelliga organismer med cellkärna</strong>, som amöbor och encelliga alger. Du känner redan igen skillnaden mellan celler med och utan kärna från kapitel 2.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade3/rikena.png\" alt=\"Bild 3.8 De fem rikena. Bilderna är förenklade.\"><figcaption><strong>Bild 3.8</strong> De fem rikena. Bilderna är förenklade.</figcaption></figure>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Rike</th><th>Cell</th><th>Hur får de näring?</th><th>Exempel</th></tr><tr><td><strong>Djur</strong></td><td>med cellkärna, utan cellvägg</td><td>äter andra organismer</td><td>räv, älg, gädda, myra</td></tr><tr><td><strong>Växter</strong></td><td>med cellkärna, cellvägg, kloroplaster</td><td>fotosyntes</td><td>tall, blåbär, björk, mossa</td></tr><tr><td><strong>Svampar</strong></td><td>med cellkärna och cellvägg, utan kloroplaster</td><td>tar upp näring från död eller levande materia</td><td>flugsvamp, mögel, jäst</td></tr><tr><td><strong>Bakterier</strong></td><td>utan cellkärna</td><td>olika sätt: några bryter ner, några gör fotosyntes</td><td>mjölksyrabakterier, tarmbakterier</td></tr><tr><td><strong>Encelliga med kärna</strong></td><td>en enda cell med cellkärna</td><td>olika sätt</td><td>amöba, encelliga alger</td></tr></table></div>"]}, {"ikon": "📖", "titel": "Svampar är varken djur eller växter", "text": ["<p>Svampar ser ofta ut som växter, men de gör ingen fotosyntes. Det du plockar när du plockar kantareller är bara svampens fruktkropp. Själva svampen är ett nät av tunna trådar, <strong>mycel</strong>, som växer i marken och bryter ner död materia. Många svampar lever också tillsammans med träd och hjälper trädens rötter att ta upp vatten och näring. Svampar och bakterier är viktiga <strong>nedbrytare</strong>.</p>"]}, {"ikon": "📖", "titel": "Laven: en samlevnad", "text": ["<p>En lav ser ut som en enda organism men är två: en svamp och en alg (eller bakterie) som gör fotosyntes. Svampen ger skydd och vatten, och algen ger socker. Båda har nytta av varandra, och det kallas <strong>symbios</strong>. Garnlaven i bild 3.6 är en lav.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Visste du?</span>Du är också en art: <em>Homo sapiens</em>. Det betyder ”den kloka människan”.</div>"]}, {"ikon": "📖", "titel": "Namn på latin", "text": ["<p>Samma växt kan heta olika saker på olika språk. Därför har varje art ett <strong>vetenskapligt namn</strong> med två latinska ord. Det första är släktet och det andra är arten. Första ordet skrivs med stor bokstav, och hela namnet skrivs med kursiv stil. Tallen heter <em>Pinus sylvestris</em> och granen <em>Picea abies</em>. Systemet infördes av den svenske naturforskaren Carl von Linné på 1700-talet. Arter som liknar varandra hör till samma släkte, och släkten som liknar varandra hör till samma familj.</p>"], "fragor": [{"f": "Nämn de fem rikena.", "svar": "Djur, växter, svampar, bakterier och encelliga organismer med cellkärna."}, {"f": "Vad skiljer en svamp från en växt?", "svar": "Svampen gör ingen fotosyntes utan tar upp näring från död eller levande materia. Den har cellvägg av annat material än växten."}, {"f": "Hur skrivs en arts vetenskapliga namn, och vad står de två orden för?", "svar": "Två latinska ord, släktnamn och artnamn, t.ex. Pinus sylvestris (tall). Första ordet har stor bokstav."}, {"f": "Vad är en lav?", "svar": "En samlevnad mellan en svamp och en alg eller bakterie som gör fotosyntes. De hjälper varandra."}]}], "begrepp": [{"term": "Lav", "forklaring": "En samlevnad mellan en svamp och en alg eller bakterie som gör fotosyntes."}, {"term": "Rike", "forklaring": "En av de största grupperna som organismer delas in i."}, {"term": "Vetenskapligt namn", "forklaring": "Artens namn på latin, med två ord."}]}, "fordjupning": {"sektioner": [{"ikon": "📖", "titel": "Rikena", "text": ["<p>Hur delar man in organismer i grupper? Ett sätt är att gruppera dem efter hur lika de ser ut. Ett annat och mer tillförlitligt sätt är att gruppera efter <strong>släktskap</strong>: vilka som har gemensamma förfäder.</p>", "<p>Yttre likhet kan vara missvisande. En haj är en fisk. En delfin är ett däggdjur: den andas luft med lungor, föder levande ungar och ger di. Ändå ser de lika ut, eftersom en strömlinjeformad kropp med fenor är en bra anpassning till ett liv i vatten. När olika grupper utvecklar liknande drag på grund av liknande miljö kallas det <strong>konvergent evolution</strong>. Likheterna beror alltså på samma slags urval, inte på att de är nära släkt.</p>", "<p>Därför tittar forskare i dag mycket på arvsmassan (DNA). Ju mer lika DNA två arter har, desto närmare släkt är de oftast. Släktskap ritas som ett <strong>släktträd</strong>, där grenarna visar hur arter har delat sig från gemensamma förfäder.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Varför kan en delfin och en haj se lika ut fast delfinen är närmare släkt med en ko?</div>"]}, {"ikon": "📖", "titel": "Att läsa ett släktträd", "text": ["<p>I ett släktträd visar varje förgrening en gemensam förfader. Två arter som delar en förfader som levde nyligen är nära släkt. De som delar en förfader som levde för mycket längre sedan är mer avlägset släkt. Man ska läsa släktskapet utifrån förgreningarna, inte utifrån hur nära varandra namnen står. Linné grupperade efter likhet. Efter att man lärt sig mycket mer om evolution och DNA har man ändrat många grupper så att de speglar släktskap.</p>", "<p>I grundtexten lärde du dig att en art är individer som kan få fortplantningsdugliga ungar med varandra. Det är en bra utgångspunkt, men den har gränser. Naturen är ofta mer flytande än våra grupper.</p>", "<p><strong>Hybrider.</strong> Ibland kan individer av två närstående arter få ungar tillsammans. Hybrider mellan brunbjörn och isbjörn har till exempel hittats i naturen. Då blir gränsen mellan arterna oskarp. I vissa fall är hybriderna sterila, som mulåsnan, och då håller artbegreppet. I andra fall kan hybriderna själva få ungar.</p>", "<p><strong>Organismer utan parning.</strong> Bakterier förökar sig genom att dela sig. Ingen parning sker, så definitionen ”kan få ungar med varandra” går inte att tillämpa. För sådana organismer gruppar forskare i stället efter likhet i DNA och egenskaper.</p>", "<p><strong>Slutsats.</strong> Artbegreppet är ett redskap som människan har skapat för att ordna naturen. Det fungerar bra för många organismer men inte för alla, och forskare använder därför flera olika sätt att avgränsa arter.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Varför fungerar definitionen ”kan få fortplantningsdugliga ungar med varandra” dåligt för bakterier?</div>"]}], "begrepp": [{"term": "Artbegrepp", "forklaring": "Definition av vad som räknas som en art."}, {"term": "Hybrid", "forklaring": "Avkomma till föräldrar av två olika arter."}, {"term": "Konvergent evolution", "forklaring": "När olika arter utvecklar liknande drag på grund av liknande miljö."}, {"term": "Släktskap", "forklaring": "Hur nära gemensam förfader olika arter har."}, {"term": "Släktträd", "forklaring": "Ett diagram som visar hur arter är släkt med varandra."}, {"term": "Steril", "forklaring": "Oförmögen att få egna ungar."}]}}, nivaStandard: "vanlig"};
innehall["biologi-m-3-2-2"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📖", "titel": "Bestämningsnycklar", "text": ["<p>En <strong>bestämningsnyckel</strong> hjälper dig att ta reda på vad en art heter. Du gör ett val i taget med två alternativ.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade3/nyckel.png\" alt=\"\"></figure>", "<p>Så gör du:</p>", "<ol><li>Titta noga på trädet.</li><li>Läs det första valet. Vilket alternativ stämmer?</li><li>Följ pilen till nästa val.</li><li>Fortsätt tills du kommer fram till ett namn.</li><li>Kontrollera i en bok eller app.</li></ol>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>En bestämningsnyckel leder dig steg för steg till artens namn. Du jämför kännetecken.</div>"]}, {"ikon": "✏️", "titel": "Öva: Bestämningsnycklar", "text": [], "ovningar": [{"typ": "ringa", "fraga": "Vad är en bestämningsnyckel?", "val": ["En serie val som leder till artens namn", "En nyckel till en dörr", "En lista på alla djur"], "ratt": 0}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["Man väljer mellan två alternativ i taget.", "Man gissar utan att titta.", "Man kontrollerar svaret i en bok."], "ratt": [true, false, true]}, {"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["barr", "kännetecken", "nyckeln"], "meningar": ["Tall och gran har §.", "Man jämför § på växten.", "Man följer § steg för steg."], "ratt": ["barr", "kännetecken", "nyckeln"]}, {"typ": "skriv", "fraga": "Vilket träd har barr som sitter ensamma runt kvisten? Använd nyckeln.", "borja": "Trädet är", "forslag": "Gran."}]}]}, "vanlig": {"sektioner": [{"ikon": "📖", "titel": "Bestämningsnycklar", "text": ["<p>Hur vet man vad en växt eller ett djur heter? Man kan använda en <strong>bestämningsnyckel</strong>. Den består av en serie val med två alternativ. Varje val leder vidare till nästa tills du har kommit fram till arten. Du jämför det du ser (<strong>kännetecken</strong>) med nyckelns påståenden.</p>", "<p>Bild 3.9 visar en nyckel för fem vanliga träd i Norrbotten. Börja överst: har trädet barr eller blad? Följ sedan pilen till nästa fråga.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade3/nyckel.png\" alt=\"Bild 3.9 En bestämningsnyckel för fem träd. Tall och gran har barr, de övriga har blad.\"><figcaption><strong>Bild 3.9</strong> En bestämningsnyckel för fem träd. Tall och gran har barr, de övriga har blad.</figcaption></figure>"]}, {"ikon": "📖", "titel": "Så använder du en nyckel", "text": ["<ol><li>Titta noga på hela växten. Notera blad eller barr, kvist och bark.</li><li>Läs det första valet och bestäm vilket alternativ som stämmer.</li><li>Följ pilen till nästa val. Fortsätt tills du kommer fram till ett namn.</li><li>Kontrollera: stämmer artens beskrivning och bild i en bok eller app med det du ser?</li><li>Om det inte stämmer: gå tillbaka och prova det andra alternativet.</li></ol>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Du hittar ett träd med barr som sitter två och två i knippe. Vilket träd är det enligt nyckeln?</div>"]}, {"ikon": "📖", "titel": "Så gör du en egen nyckel", "text": ["<p>Välj några arter som du vill kunna skilja åt. Hitta ett kännetecken som delar gruppen i två: till exempel ”har fjädrar” eller ”saknar fjädrar”. Dela sedan varje halva med nästa kännetecken, tills varje art har fått sin egen plats. Bra kännetecken är sådana som alla kan se och som inte beror på årstid eller storlek, som antal ben, bladets form eller om växten har blommor.</p>"], "fragor": [{"f": "Vad är en bestämningsnyckel?", "svar": "En serie val med två alternativ där varje val leder till nästa tills man kommer fram till arten."}, {"f": "Använd nyckeln på bild 3.9. Vilket träd har barr som sitter ensamma runt kvisten?", "svar": "Gran."}, {"f": "Varför ska nyckeln bara ha två alternativ i varje steg?", "svar": "Det gör valet tydligt: antingen stämmer det ena eller det andra."}, {"f": "Hitta på ett eget första steg i en nyckel för tre djur: gädda, räv och duva.", "svar": "T.ex. Har djuret fjädrar? Ja: duva. Nej: gå vidare. Lever det i vatten? Ja: gädda. Nej: räv."}]}], "begrepp": [{"term": "Bestämningsnyckel", "forklaring": "En serie val med två alternativ som leder till artens namn."}, {"term": "Kännetecken", "forklaring": "En egenskap som man kan se och som skiljer arter åt."}]}}, nivaStandard: "vanlig"};
innehall["biologi-m-3-2-3"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📖", "titel": "Anpassningar", "text": ["<p>En <strong>anpassning</strong> är ett drag som hjälper en art att klara sin miljö.</p>", "<p>Fjällräven har tjock päls och små öron. Då fryser den inte lika lätt. Renen har breda klövar som bär på snö.</p>", "<p>Individer av en art är inte exakt lika. Det kallas <strong>variation</strong>.</p>", "<p>De som passar bäst i miljön överlever oftare och får fler ungar. Draget går i arv. Det kallas <strong>naturligt urval</strong>.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade3/urval.png\" alt=\"\"></figure>", "<p>Exempel: ljusa fjärilar syns inte på ljus bark. Fåglarna tar de mörka först. Då blir de ljusa fler.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Anpassningar uppstår genom naturligt urval under många generationer. En individ bestämmer inte själv.</div>"]}, {"ikon": "✏️", "titel": "Öva: Anpassningar", "text": [], "ovningar": [{"typ": "ringa", "fraga": "Vad är en anpassning?", "val": ["Ett drag som hjälper arten i sin miljö", "En sjukdom", "Ett namn"], "ratt": 0}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["Individer av samma art är olika.", "En individ väljer sin anpassning.", "Drag som passar blir vanligare."], "ratt": [true, false, true]}, {"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["ungar", "urval", "variation"], "meningar": ["Skillnader mellan individer kallas §.", "De som passar bäst får fler §.", "Det kallas naturligt §."], "ratt": ["variation", "ungar", "urval"]}, {"typ": "skriv", "fraga": "Ge ett exempel på en anpassning.", "borja": "Ett exempel är", "forslag": "Till exempel fjällrävens tjocka päls eller renens breda klövar."}]}]}, "vanlig": {"sektioner": [{"ikon": "📖", "titel": "Anpassningar", "text": ["<p>Varje art är anpassad till sin miljö. En <strong>anpassning</strong> är ett drag hos arten, till exempel i byggnaden, hur kroppen fungerar eller hur den beter sig, som gör att den klarar sig i sin livsmiljö. Titta på fjällräven i bild 3.5. Den har tjock päls som är vit på vintern, små öron som släpper ut lite värme och ligger ofta i en snölya. Rödräven har större öron och längre ben och klarar sig bättre i skogen.</p>", "<p>Andra exempel är tallens vaxade, smala barr som tål torka och kyla, och renens breda klövar som bär på snö. Anpassningar är inte något en individ bestämmer sig för. De har uppstått över många generationer.</p>"]}, {"ikon": "📖", "titel": "Hur uppstår en anpassning? Naturligt urval", "text": ["<p>Individerna av en art är aldrig exakt likadana. Det finns <strong>variation</strong>, och en del av den går i arv. Om en variant klarar miljön bättre överlever de individerna oftare och får fler ungar, och dragen går vidare. Efter många generationer är draget vanligare. Det kallas <strong>naturligt urval</strong>. Du läser mer om evolutionen i kapitel 9.</p>", "<p>Ett klassiskt exempel är pepparfjärilen i England. Den finns i en ljus och en mörk variant. På 1800-talet, när sot från fabriker gjorde trädstammarna mörka, blev de mörka fjärilarna vanligare, för de syntes sämre för fåglarna. När luften blev renare och barken ljusare minskade de mörka igen. Försök där man satt ut fjärilar har visat att fåglar tar de fjärilar som syns bäst.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Bild 3.10 visar en skog med ljus bark. Vad skulle hända med fjärilarna i en skog med mörk, sotig bark?</div>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade3/urval.png\" alt=\"Bild 3.10 Naturligt urval i tre steg, med ljusa och mörka fjärilar på en ljus trädstam. Bilden är förenklad.\"><figcaption><strong>Bild 3.10</strong> Naturligt urval i tre steg, med ljusa och mörka fjärilar på en ljus trädstam. Bilden är förenklad.</figcaption></figure>"], "fragor": [{"f": "Vad är en anpassning? Ge ett exempel.", "svar": "Ett drag hos en art som gör att den klarar sin miljö, t.ex. fjällrävens tjocka päls och små öron."}, {"f": "Varför överlever de ljusa pepparfjärilarna oftare i en skog med ljus bark?", "svar": "De är svåra för fåglar att se. De mörka syns lättare och blir uppätna oftare."}, {"f": "Förklara med variation, urval och ärftlighet hur en art kan ändras över generationer.", "svar": "Individerna är olika (variation). De med de mest passande dragen överlever och får fler ungar (urval). Dragen går i arv, så de blir vanligare."}, {"f": "Varför är en anpassning ingen sak som en individ bestämmer sig för?", "svar": "Anpassningar uppstår genom att gener som passar blir vanligare över generationer, inte genom att en individ väljer."}]}], "begrepp": [{"term": "Anpassning", "forklaring": "Ett drag som gör att en art klarar sin miljö."}, {"term": "Naturligt urval", "forklaring": "De individer som passar bäst i miljön överlever oftare och får fler ungar."}, {"term": "Variation", "forklaring": "Skillnader mellan individer av samma art."}]}, "fordjupning": {"sektioner": [{"ikon": "📖", "titel": "Anpassningar", "text": ["<p>Naturligt urval är inte bara något som hände förr. Du kan se det ske i dag, till exempel när bakterier blir motståndskraftiga mot antibiotika.</p>", "<p>I en stor bakteriepopulation finns en liten variation: någon enstaka bakterie har av en slump en gen som gör den mindre känslig för ett visst antibiotikum. När man ger antibiotikan dör de flesta bakterierna, men de resistenta överlever. De delar sig och blir många. Efter en tid består populationen mest av resistenta bakterier. Det är <strong>naturligt urval</strong>: variation fanns redan, antibiotikan valde ut vilka som överlevde, och egenskapen ärvdes. Ingen bakterie ”lärde sig” att bli resistent.</p>", "<p>Eftersom bakterier delar sig snabbt kan det gå på bara några år. Därför är det viktigt att antibiotika används bara när det behövs och att man tar hela kuren. Då minskar risken att resistenta bakterier får ta över.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Varför är det fel att säga att bakterien ”anpassade sig” genom att bestämma sig för att bli resistent?</div>"]}, {"ikon": "📖", "titel": "Gränser för urvalet", "text": ["<p>Urvalet kan bara arbeta med variation som redan finns. En art som saknar de gener som behövs kan inte ”välja” dem, och om miljön förändras för snabbt hinner arten inte anpassa sig. Därför är stor genetisk variation en tillgång, och därför hänger de två delarna av det här kapitlet ihop: mångfald på genetisk nivå är det som gör att arter kan anpassa sig.</p>"]}], "begrepp": [{"term": "Antibiotika", "forklaring": "Läkemedel som dödar eller hämmar bakterier. Verkar inte mot virus."}, {"term": "Resistens", "forklaring": "Förmåga att tåla ett ämne som annars dödar eller skadar."}]}}, nivaStandard: "vanlig"};
innehall["biologi-m-3-2-l"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "🧪", "titel": "Labb 3.2 Artbestämning med nyckel", "text": ["<p><strong>Fråga:</strong> Vilka träd finns på skolgården?</p>", "<p>Du behöver: nyckeln, mobil och papper.</p>", "<ol><li>Välj ett träd. Ta bilder på trädet, barken och bladen.</li><li>Följ nyckeln steg för steg.</li><li>Skriv namnet på trädet.</li><li>Gör samma sak med tre träd till.</li><li>Skriv resultatet i tabellen.</li></ol>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Träd</th><th>Kännetecken</th><th>Namn</th></tr><tr><td>1</td><td></td><td></td></tr><tr><td>2</td><td></td><td></td></tr><tr><td>3</td><td></td><td></td></tr></table></div>", "<p><strong>Säkerhet:</strong> Smaka inte på växter eller bär. Tvätta händerna efteråt.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Kontrollera alltid namnet i en bok eller app.</div>"]}, {"ikon": "✏️", "titel": "Öva: Labb 3.2 Artbestämning med nyckel", "text": [], "ovningar": [{"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["bilder", "kännetecken", "nyckeln"], "meningar": ["Jag följde § steg för steg.", "Jag tittade på trädets §.", "Jag tog § för att komma ihåg."], "ratt": ["nyckeln", "kännetecken", "bilder"]}, {"typ": "skriv", "fraga": "Vilka träd hittade du?", "borja": "Jag hittade", "forslag": "Egna resultat, till exempel tall, gran och björk."}, {"typ": "skriv", "fraga": "Var något svårt? Skriv vad.", "borja": "Det var svårt att", "forslag": "Egna svar."}]}]}, "vanlig": {"sektioner": [{"ikon": "🧪", "titel": "Labb 3.2 Artbestämning med nyckel", "text": ["<p>Du ska använda en bestämningsnyckel för att bestämma träd i närområdet och dokumentera med bild.</p>", "<p><strong>Frågeställning:</strong> Vilka arter av träd finns på skolgården eller i närmaste park?</p>", "<p><strong>Hypotes:</strong> Skriv vilka träd du tror att du hittar.</p>", "<p><strong>Material:</strong> nyckeln i bild 3.9, mobilkamera, papper och penna, gärna en trädbok eller artapp.</p>"]}, {"ikon": "📖", "titel": "Gör så här", "text": ["<ol><li>Välj ett träd. Ta en bild på hela trädet, barken och bladen eller barren. Plocka bara löv som redan ligger på marken.</li><li>Använd nyckeln i bild 3.9 och följ den steg för steg. Skriv upp vilka val du gör.</li><li>Skriv trädets svenska och vetenskapliga namn. Kontrollera i en bok eller app.</li><li>Gör likadant med minst fyra olika träd. Skriv resultatet i tabellen.</li><li>Om du hittar ett träd som inte finns i nyckeln: skriv vilka kännetecken det har och vilket steg som inte stämmer.</li></ol>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Bra att veta</span>Samma art kan se olika ut. Titta på flera blad och kontrollera med flera kännetecken.</div>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Träd nr</th><th>Kännetecken</th><th>Valen i nyckeln</th><th>Svenskt namn</th><th>Vetenskapligt namn</th></tr><tr><td>1</td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td></tr></table></div>"]}, {"ikon": "❓", "titel": "Frågor", "text": ["<ol><li>Vilket kännetecken var lättast att använda, och vilket var svårast?</li><li>Fanns det träd som du inte kunde bestämma med nyckeln? Varför?</li><li>Hur kan du kontrollera att du fått rätt art?</li><li>Vad var svårt i undersökningen, och hur skulle du göra annorlunda nästa gång?</li></ol>", "<p class=\"not\">Säkerhet: Smaka aldrig på växter, bär eller svampar. Plocka inte skyddade växter. Tvätta händerna efteråt.</p>"]}], "begrepp": [{"term": "Bestämma", "forklaring": "Att ta reda på vilken art något är."}, {"term": "Dokumentera", "forklaring": "Att skriva och fotografera det du gör."}]}}, nivaStandard: "vanlig"};
innehall["biologi-m-3-s"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📌", "titel": "Sammanfattning", "text": ["<p>Läs orden och titta på bilderna. Du kan komma tillbaka hit när du läser.</p>", "<p>Här är allt det viktigaste i kapitlet. Läs det en gång till.</p>", "<ul class=\"viktigast\"><li>Biologisk mångfald är variationen av liv: gener, arter och ekosystem.</li></ul>", "<ul class=\"viktigast\"><li>Ekosystemtjänster är sådant naturen gör som vi har nytta av. Det finns fyra typer.</li></ul>", "<ul class=\"viktigast\"><li>Hoten är ändrad markanvändning, överuttag, klimatförändringar, föroreningar och invasiva arter. Rödlistan visar hotade arter.</li></ul>", "<ul class=\"viktigast\"><li>Fjällräven och gammal skog är exempel på mångfald som behöver skydd i Norrbotten.</li></ul>", "<ul class=\"viktigast\"><li>Det finns fem riken. En bestämningsnyckel leder till artens namn.</li></ul>", "<ul class=\"viktigast\"><li>Anpassningar uppstår genom naturligt urval under många generationer.</li></ul>"]}], "begrepp": [{"term": "anpassning", "forklaring": "ett drag som hjälper en art att klara sin miljö"}, {"term": "art", "forklaring": "en sort av växt, djur eller svamp"}, {"term": "bestämningsnyckel", "forklaring": "en serie val som leder till artens namn"}, {"term": "biologisk mångfald", "forklaring": "all variation av liv: gener, arter och ekosystem"}, {"term": "ekosystem", "forklaring": "alla växter, djur och svampar i ett område och miljön de lever i"}, {"term": "ekosystemtjänst", "forklaring": "något naturen gör som vi har nytta av"}, {"term": "gen", "forklaring": "en del av arvsmassan som bestämmer en egenskap"}, {"term": "invasiv art", "forklaring": "en främmande art som sprider sig och skadar naturen"}, {"term": "konsument", "forklaring": "äter andra organismer"}, {"term": "lav", "forklaring": "en svamp och en alg som lever ihop"}, {"term": "naturligt urval", "forklaring": "de som passar bäst i miljön överlever och får fler ungar"}, {"term": "nedbrytare", "forklaring": "bryter ner döda växter och djur"}, {"term": "näringsväv", "forklaring": "många näringskedjor som hänger ihop"}, {"term": "pollinering", "forklaring": "när pollen flyttas mellan blommor så att de kan bilda frön"}, {"term": "population", "forklaring": "alla individer av en art i ett område"}, {"term": "producent", "forklaring": "gör egen mat, till exempel en växt"}, {"term": "rike", "forklaring": "en stor grupp av organismer, till exempel djur eller svampar"}, {"term": "rödlista", "forklaring": "lista över arter som kan dö ut"}, {"term": "signalart", "forklaring": "en art som visar att miljön är värdefull"}, {"term": "variation", "forklaring": "skillnader mellan individer av samma art"}]}, "vanlig": {"sektioner": [{"ikon": "📌", "titel": "Sammanfattning", "text": ["<ul><li><strong>Biologisk mångfald</strong> är variationen av liv på tre nivåer: gener, arter och ekosystem.</li><li>En <strong>art</strong> är individer som kan få fortplantningsdugliga ungar. En <strong>population</strong> är alla individer av en art i ett område.</li><li>Ett ekosystem med många arter och stor genetisk variation är mer motståndskraftigt mot störningar.</li><li>Människan är beroende av <strong>ekosystemtjänster</strong>: försörjande, reglerande, stödjande och kulturella.</li><li>De största hoten är ändrad markanvändning, överuttag, klimatförändringar, föroreningar och invasiva arter.</li><li>I Sverige följs arternas läge i <strong>rödlistan</strong>. I Rödlistan 2025 var 5 217 arter rödlistade och 2 373 hotade.</li><li>Mångfalden skyddas genom skyddade områden, lagar, internationella avtal och genom vad vi gör som individer.</li><li>Organismer delas in i <strong>riken</strong>: djur, växter, svampar, bakterier och encelliga med cellkärna. Varje art har ett vetenskapligt namn med två ord.</li><li>Med en <strong>bestämningsnyckel</strong> kommer man fram till en arts namn genom att välja mellan två alternativ i taget.</li><li>En <strong>anpassning</strong> är ett drag som gör att en art klarar sin miljö. Anpassningar uppstår genom <strong>naturligt urval</strong> över generationer.</li></ul>"]}], "begrepp": [{"term": "Anpassning", "forklaring": "Ett drag som gör att en art klarar sin miljö."}, {"term": "Art", "forklaring": "Individer som kan få fortplantningsdugliga ungar med varandra."}, {"term": "Bestämningsnyckel", "forklaring": "Serie val med två alternativ som leder till artens namn."}, {"term": "Biologisk mångfald", "forklaring": "Variationen av liv: genetisk mångfald, artmångfald och ekosystemmångfald."}, {"term": "Ekosystem", "forklaring": "Alla organismer i ett område och den miljö de lever i."}, {"term": "Ekosystemtjänst", "forklaring": "Något naturen gör som människan har nytta av."}, {"term": "Gen", "forklaring": "Del av arvsmassan (DNA) som styr en egenskap."}, {"term": "Invasiv art", "forklaring": "Främmande art som människan fört in och som sprider sig och skadar inhemska arter."}, {"term": "Konsument", "forklaring": "Organism som äter andra organismer."}, {"term": "Lav", "forklaring": "Samlevnad mellan en svamp och en alg eller bakterie som gör fotosyntes."}, {"term": "Livsmiljö", "forklaring": "Platsen där en art kan leva och föröka sig."}, {"term": "Naturligt urval", "forklaring": "De individer som passar bäst i miljön överlever oftare och får fler ungar."}, {"term": "Nedbrytare", "forklaring": "Organism som bryter ner dött material till näring."}, {"term": "Näringsväv", "forklaring": "Flera näringskedjor som hänger ihop."}, {"term": "Pollinering", "forklaring": "Pollen förs mellan blommor så att de kan bilda frön."}, {"term": "Population", "forklaring": "Alla individer av en art inom ett område."}, {"term": "Producent", "forklaring": "Organism som gör sin egen näring genom fotosyntes."}, {"term": "Rike", "forklaring": "En av de största grupperna som organismer delas in i."}, {"term": "Rödlista", "forklaring": "Förteckning över arter och deras risk att dö ut."}, {"term": "Signalart", "forklaring": "Art som visar att en miljö har höga naturvärden."}, {"term": "Symbios", "forklaring": "Samlevnad där båda parter har nytta av varandra."}, {"term": "Variation", "forklaring": "Skillnader mellan individer av samma art."}, {"term": "Vetenskapligt namn", "forklaring": "Artens latinska namn med två ord: släkte och art."}, {"term": "Överuttag", "forklaring": "När människan tar mer ur naturen än vad som hinner växa till."}]}}, nivaStandard: "vanlig"};
innehall["biologi-m-3-t"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📝", "titel": "Testa dig själv", "text": ["Nu får du visa vad du har lärt dig. Du kan titta i kapitlet om du vill."], "ovningar": [{"typ": "ringa", "fraga": "Vad är genetisk mångfald?", "val": ["Variation i gener inom en art", "Antalet ekosystem", "Antalet individer"], "ratt": 0}, {"typ": "streck", "fraga": "Dra streck till rätt förklaring.", "vanster": ["Art", "Population", "Ekosystem", "Rödlista"], "hoger": ["alla individer av en art i ett område", "arter och miljö tillsammans", "individer som kan få ungar", "lista över hotade arter"], "ratt": ["individer som kan få ungar", "alla individer av en art i ett område", "arter och miljö tillsammans", "lista över hotade arter"]}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["Bin pollinerar blommor.", "Svampar är växter.", "Överfiske är ett hot.", "En individ väljer sin anpassning.", "Garnlav är en signalart.", "En nyckel har två alternativ i varje steg."], "ratt": [true, false, true, false, true, true]}, {"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["bestämningsnyckel", "ekosystemtjänst", "rödlistan"], "meningar": ["Forskarna visar hotade arter i §.", "Pollinering är en §.", "Med en § kan man bestämma en art."], "ratt": ["rödlistan", "ekosystemtjänst", "bestämningsnyckel"]}, {"typ": "siffror", "fraga": "Sätt i ordning. Skriv 1, 2, 3 och 4.", "delar": ["Individerna som passar bäst får fler ungar", "Individerna är olika", "Draget blir vanligare", "Några passar miljön bättre"], "ratt": [3, 1, 4, 2]}, {"typ": "skriv", "fraga": "Varför är många arter bra för naturen?", "borja": "Många arter är bra eftersom", "forslag": "Fler arter kan ta över om en art försvinner, så naturen klarar förändringar bättre."}, {"typ": "ringa", "fraga": "Vilket rike gör fotosyntes?", "val": ["Växter", "Djur", "Svampar"], "ratt": 0}, {"typ": "skriv", "fraga": "Ge ett exempel på ett hot mot mångfalden.", "borja": "Ett hot är", "forslag": "Till exempel avverkad skog eller överfiske."}]}]}, "vanlig": {"sektioner": [{"ikon": "📖", "titel": "Del A · Välj ett alternativ", "text": ["Uppgifterna liknar uppgifterna på nationella prov i biologi. Personer, annonser och mätvärden är påhittade."], "ovningar": [{"typ": "ringa", "fraga": "Vilket alternativ beskriver genetisk mångfald?", "val": ["Antalet arter i en skog.", "Variationen i gener mellan individer av samma art.", "Antalet olika ekosystem i ett land.", "Antalet individer i en population."], "ratt": 1}, {"typ": "ringa", "fraga": "Vilket är ett exempel på en reglerande ekosystemtjänst?", "val": ["Virke från skogen.", "Bär och svamp att plocka.", "Humlor som pollinerar blåbärsris.", "En vandring i fjällen."], "ratt": 2}, {"typ": "ringa", "fraga": "I en barrskog blir det plötsligt mycket färre skogssorkar. Vad händer troligen först?", "val": ["Blåbärsriset minskar.", "Pärlugglorna får mindre mat.", "Renarna blir fler.", "Lavarna dör."], "ratt": 1}, {"typ": "ringa", "fraga": "Vilket rike tillhör en organism som inte gör fotosyntes, har cellkärna och tar upp näring från död materia?", "val": ["Växter", "Svampar", "Bakterier", "Djur"], "ratt": 1}]}, {"ikon": "📖", "titel": "Del B · Svara kort", "text": [], "ovningar": [{"typ": "fri", "fraga": "Uppge två ekosystemtjänster som en våtmark ger.", "forslag": "T.ex. de renar vatten, minskar översvämningar, binder kol och är livsmiljö för många arter."}, {"typ": "fri", "fraga": "Blomsterlupinen är en invasiv art. Beskriv vad det innebär.", "forslag": "En invasiv art är en främmande art som människan fört in och som sprider sig och skadar eller tränger undan inhemska arter."}]}, {"ikon": "📖", "titel": "Del C · Tolka resultat och förklara", "text": [], "ovningar": [{"typ": "fri", "fraga": "En klass räknade växtarter i provrutor på 1 m² vid två ängar. Den ena betas av kor. Den andra har inte betats på tio år och har börjat växa igen. Resultaten är påhittade.<br><div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Äng</th><th>Ruta 1</th><th>Ruta 2</th><th>Ruta 3</th></tr><tr><td>Betad äng</td><td>21</td><td>18</td><td>24</td></tr><tr><td>Igenvuxen äng</td><td>9</td><td>12</td><td>6</td></tr></table></div>a) Räkna ut medelvärdet av antalet arter för varje äng.<br>b) Ge en möjlig förklaring till skillnaden.", "forslag": "a) Betad äng: (21 + 18 + 24) / 3 = 21. Igenvuxen äng: (9 + 12 + 6) / 3 = 9. b) T.ex. betet håller ängen öppen så att fler arter får ljus, medan en igenvuxen äng domineras av få höga växter som skuggar och tränger undan andra."}, {"typ": "fri", "fraga": "Sven påstår: ”Naturligt urval betyder att varje individ anpassar sig när miljön ändras.” Förklara varför han har fel.", "forslag": "Naturligt urval verkar på populationer över många generationer. Individerna är olika redan från början. De med de mest passande dragen överlever och får fler ungar, och dragen går i arv. En enskild individ ändrar inte sina gener för att miljön ändras."}]}, {"ikon": "📖", "titel": "Del D · Resonera och ta ställning", "text": [], "ovningar": [{"typ": "fri", "fraga": "Kommunen vill bygga ett nytt bostadsområde i en gammal skog där det växer garnlav. Vilka konsekvenser kan bygget få för den biologiska mångfalden? Ta ställning till om skogen ska bebyggas och motivera med minst två argument.", "forslag": "Öppet svar. Ett välutvecklat svar nämner att gammal skog har arter som är beroende av gamla träd och död ved, att garnlav är en signalart, att livsmiljöer tar hundratals år att återskapa, och väger detta mot behovet av bostäder och jobb. Minst två argument med motivering, gärna med en motsatt synpunkt."}, {"typ": "fri", "fraga": "Wilma påstår: ”Rödlistan visar att det går sämre för naturen eftersom antalet rödlistade arter har ökat sedan 2005.” Använd bild 3.4 och rutan Granska kritiskt. Har Wilma rätt? Förklara.", "forslag": "Nej, inte nödvändigtvis. Antalet bedömda arter ökade från cirka 19 000 till drygt 23 000, så fler nya arter kan ha blivit rödlistade bara för att forskarna hade bedömt dem. Man måste jämföra andelen eller samma arter över tid. Rödlistan visar ändå att många arter är hotade."}]}, {"ikon": "📖", "titel": "Del E · Planera och resonera", "text": [], "ovningar": [{"typ": "fri", "fraga": "Elias tror att det finns fler arter av lavar i gammal skog än i ung, planterad skog. Planera en undersökning som kan pröva hans idé. Beskriv vad du ska räkna eller mäta, hur du gör jämförelsen rättvis och hur du dokumenterar resultatet.", "forslag": "Räkna och jämför lavarter i flera lika stora provrutor eller på lika många träd i gammal och ung skog. Håll storlek, tid på året, trädslag och sökmetod lika (rättvist försök). Skriv in antalet i en tabell, räkna medelvärde och dokumentera med foton och anteckningar. Flera upprepningar gör slutsatsen säkrare."}, {"typ": "fri", "fraga": "Abborre, gädda, fiskgjuse och djurplankton lever i samma sjö. Ordna dem i en näringskedja och lägg till en producent först i kedjan. Förklara sedan vad som kan hända med gäddorna om nästan alla abborrar fångas.", "forslag": "Producent (t.ex. alger) → djurplankton → abborre → gädda → fiskgjuse. Om nästan alla abborrar fångas får gäddorna mindre mat och kan minska. Djurplankton kan öka eftersom färre abborrar äter dem. Gäddorna kan välja andra byten, så effekten beror på hur många alternativ som finns."}]}]}, "fordjupning": {"sektioner": [{"ikon": "💭", "titel": "Resonera och ta ställning", "text": ["Uppgifterna liknar de svåraste uppgifterna på nationella prov. Personer, rubriker och mätvärden är påhittade. Svara utförligt och resonera i flera led."], "ovningar": [{"typ": "fri", "fraga": "En kommun planterar en granplantage i stället för en blandskog. Efter tio år kommer en torr sommar följd av en granbarkborreinvasion. a) Förklara med försäkringseffekten varför en blandskog troligen klarar det bättre. b) Förklara varför det inte räcker att räkna antalet träd. c) Ge ett argument som talar för plantagen och väg det mot ditt svar på a).", "forslag": "a) På en blandskog har träden olika toleranser. Några klarar torka eller angrepp bättre, så en del av skogen överlever (försäkringseffekt). En granplantage har bara en art som alla drabbas av samma sak, så allt kan slås ut. b) Det beror på vilka arter och vilka egenskaper de har: många individer av samma art ger ingen försäkring. c) T.ex. snabb tillväxt och enkel avverkning ger vinst, men det är ett riskabelt val. Ett välutvecklat svar väger vinst mot risk."}, {"typ": "fri", "fraga": "På en klippkust försvinner havsuttrarna. Efter en tid är tångskogen borta. a) Förklara kedjan av orsaker i flera led. b) Vad kallas fenomenet? c) Varför är det svårt att veta säkert att just uttern är orsaken? Föreslå hur man kan undersöka det.", "forslag": "a) Utan uttrar ökar sjöborrarna, som äter tången. Tången minskar och tångskogen försvinner, och alla arter som lever där försvinner också. b) Trofisk kaskad. c) Det kan finnas andra orsaker samtidigt, t.ex. temperatur eller sjukdomar. Man kan jämföra områden med och utan utter och försöka hålla övrigt lika."}, {"typ": "fri", "fraga": "En liten population av en hotad art har ökat från 20 till 120 djur tack vare skydd. Forskare oroar sig ändå. a) Förklara vad en genetisk flaskhals innebär. b) Förklara varför populationen kan ha svårt att anpassa sig trots att den ökat. c) Föreslå en åtgärd och värdera nytta och nackdelar.", "forslag": "a) En stor minskning i antalet individer leder till att mycket genetisk variation går förlorad. b) De djur som finns kan vara nära släkt och ha liten variation, så det finns färre gener som kan passa en ny miljö. Inavel kan också öka. c) T.ex. flytta in djur från en annan population. Nytta: ökad variation. Nackdelar: kostnad, risk att djuren inte passar lokalt, och de kan föra med sjukdomar."}, {"typ": "fri", "fraga": "Ett fiskebestånd har minskat i tio år, och regeringen funderar på ett fiskestopp. Fiskare säger att stoppet slår ut hela byar. a) Förklara hur överfiske kan leda till kollaps. b) Redovisa argument för och emot ett stopp. c) Ta ställning och motivera. Beskriv också vad du är osäker på.", "forslag": "a) Om man fiskar mer än vad som hinner växa till minskar beståndet. När för få vuxna fiskar finns kvar föds för få ungar, och beståndet kan kollapsa. b) För: beståndet kan återhämta sig och ge mer fisk senare. Emot: jobb försvinner på kort sikt. c) Öppet svar. Ett välutvecklat svar väger flera argument, nämner vad man är osäker på (t.ex. hur snabbt beståndet återhämtar sig) och ger motiverat svar."}, {"typ": "fri", "fraga": "Biologen Alma påstår: ”Eftersom delfiner ser ut som hajar måste de vara nära släkt.” a) Förklara varför hon har fel. b) Beskriv vad konvergent evolution är och varför den uppstår. c) Hur skulle man kunna ta reda på hur nära släkt två arter är?", "forslag": "a) De ser lika ut men är inte nära släkt: delfinen är ett däggdjur (andas luft, föder levande ungar), hajen en fisk. b) När olika grupper utvecklar liknande drag på grund av liknande miljö. Strömlinjeformad kropp är bra för snabb simning, så urvalet gynnar den hos båda. c) Jämföra DNA och se hur mycket det skiljer, och titta på fossil och uppbyggnad."}, {"typ": "fri", "fraga": "Efter ett sjukhusutbrott ger man en patient ett antibiotikum. Först blir patienten bättre, men sedan blir hen sjuk igen, och nu hjälper inte medicinen. a) Förklara med variation, urval och ärftlighet vad som har hänt. b) Varför är det en dålig idé att sluta ta antibiotikan så fort man mår bättre? c) Varför hjälper antibiotika inte mot förkylning?", "forslag": "a) Det fanns variation: några få bakterier var resistenta. Antibiotikan dödade de känsliga, så de resistenta överlevde och delade sig (urval). Resistensen ärvs, så nästa generation blev mest resistent. b) Om man slutar för tidigt överlever fler bakterier, och risken ökar att resistenta bakterier blir kvar. c) Förkylning orsakas av virus, och antibiotika verkar bara mot bakterier."}]}]}}, nivaStandard: "vanlig"};
